<script lang="ts">
  import type { Snippet } from 'svelte';
  import { game } from '../../../gameManager.js';

  interface Props {
    title: string;
    tooltip?: string;
    summaryText?: string;
    statusPill?: string;
    statusPillVariant?: 'ok' | 'warn' | 'danger';
    defaultOpen?: boolean;
    id?: string;
    children?: Snippet;
  }

  let {
    title,
    tooltip = '',
    summaryText = '',
    statusPill = '',
    statusPillVariant = 'ok',
    defaultOpen = true,
    id,
    children,
  }: Props = $props();

  function showTooltip(e: MouseEvent): void {
    e.stopPropagation();
    if (!tooltip || !game?.scheduleTooltip) return;
    const html = tooltip.replace(/\n/g, '<br>');
    game.scheduleTooltip(e, '', html, 50);
  }

  function hideTooltip(): void {
    game?.hideTooltip?.();
  }

  function handleHintClick(e: MouseEvent): void {
    e.stopPropagation();
    e.preventDefault();
  }
</script>

<details class="tr-collapsible-section" open={defaultOpen} {id}>
  <summary class="tr-section-summary">
    <div class="tr-section-summary-left">
      <div class="tr-section-heading-with-hint">
        <span class="tr-section-heading-text">{title}</span>
        {#if tooltip}
          <button
            type="button"
            class="tr-section-tooltip-hint"
            aria-label="?"
            onclick={handleHintClick}
            onmouseenter={showTooltip}
            onmouseleave={hideTooltip}
            onfocus={showTooltip}
            onblur={hideTooltip}
          >?</button>
        {/if}
      </div>
      {#if statusPill}
        <span class="tr-section-status-pill tr-section-status-pill--{statusPillVariant}">{statusPill}</span>
      {/if}
    </div>
    <div class="tr-section-summary-right">
      {#if summaryText}
        <span class="tr-section-summary-preview">{summaryText}</span>
      {/if}
      <span class="tr-section-chevron" aria-hidden="true">▾</span>
    </div>
  </summary>
  <div class="tr-section-body">
    {@render children?.()}
  </div>
</details>
