<script lang="ts">
  import { rocket } from '../../stores/rocket.svelte.ts';
  import { game } from '../../../gameManager.js';
  import { touchTooltipHandlers } from '../../ui/scheduleTooltipHelpers.ts';

  interface Props {
    title: string;
    introTooltip: string;
  }

  let { title, introTooltip }: Props = $props();

  let kpi = $derived(rocket.snapshot.kpi);
  let rt = $derived(rocket.realtime);
  let rj = $derived(rt.rj || kpi.rj);
  let rjRate = $derived(rt.rjRate || kpi.rjRate);
  let rjRatePositive = $derived(rt.rjRatePositive ?? kpi.rjRatePositive);

  const trustTooltipHandlers = touchTooltipHandlers(() => ({
    title: kpi.trustTooltipTitle,
    body: kpi.trustTooltipBody,
  }));

  function showIntroTooltip(e: MouseEvent): void {
    if (!introTooltip || !game?.scheduleTooltip) return;
    const html = introTooltip.replace(/\n/g, '<br>');
    game.scheduleTooltip(e, '', html, 50);
  }

  function hideTooltip(): void {
    game?.hideTooltip?.();
  }

  function showRjTooltip(e: MouseEvent): void {
    if (!game?.scheduleTooltip) return;
    const desc = 'Monnaie exclusive de la Team Rocket. Utilisée pour le Staking et les tirages au Rocket Casino.';
    game.scheduleTooltip(e, 'Rocket Jetons (RJ)', desc, 50);
  }
</script>

<div class="tr-banner" id="rocketTopBanner">
  <div class="tr-banner-brand">
    <div class="tr-banner-logo-badge" aria-hidden="true">R</div>
    <div class="tr-banner-identity">
      <div class="tr-banner-title-row">
        <h3 class="tr-banner-title" id="teamRocketTitleLabel">{title}</h3>
        {#if introTooltip}
          <button
            type="button"
            class="tr-section-tooltip-hint"
            aria-label="Informations Team Rocket"
            onmouseenter={showIntroTooltip}
            onmouseleave={hideTooltip}
            onfocus={showIntroTooltip}
            onblur={hideTooltip}
          >?</button>
        {/if}
      </div>
      <div class="tr-banner-subtitle tr-text-muted">Opérations clandestines & Jetons RJ</div>
    </div>
  </div>

  <div class="tr-banner-kpis">
    <!-- RJ KPI -->
    <div
      class="tr-banner-kpi-tile"
      role="button"
      tabindex="0"
      onmouseenter={showRjTooltip}
      onmouseleave={hideTooltip}
      onfocus={showRjTooltip}
      onblur={hideTooltip}
    >
      <div class="tr-banner-kpi-val-row">
        <span class="tr-banner-kpi-val tr-text-value" id="rocketKpiRjValue">{rj}</span>
        <span
          class="tr-banner-kpi-rate"
          class:is-positive={rjRatePositive}
          title="Débit de génération RJ par seconde"
        >{rjRate}</span>
      </div>
      <div class="tr-banner-kpi-lbl tr-text-muted tr-text-muted--caps">{kpi.labelRj}</div>
    </div>

    <!-- Trust KPI -->
    <div
      class="tr-banner-kpi-tile tr-trust-tile--tooltip-host"
      data-tooltip-variant="rocket-trust"
      tabindex="0"
      role="button"
      aria-label={kpi.trustTooltipTitle}
      {...trustTooltipHandlers}
    >
      <div class="tr-banner-kpi-val-row">
        <span class="tr-banner-kpi-val tr-text-value">{kpi.trustLevelText}</span>
      </div>
      <div class="tr-trust-xp-bar" class:is-max={kpi.trustIsMax} aria-hidden="true">
        <div class="tr-trust-xp-fill" style:width="{kpi.trustXpRatio.toFixed(2)}%"></div>
      </div>
      <div class="tr-banner-kpi-progress-lbl tr-text-muted tr-text-muted--caps">
        <span>{kpi.labelTrust}</span>
        <span class="tr-trust-xp-text">{kpi.trustNextXpText}</span>
      </div>
    </div>

    <!-- Loan Cap KPI -->
    <div class="tr-banner-kpi-tile">
      <div class="tr-banner-kpi-val-row">
        <span class="tr-banner-kpi-val tr-text-value tr-currency-gold">{kpi.loanCap}</span>
      </div>
      <div class="tr-banner-kpi-lbl tr-text-muted tr-text-muted--caps">{kpi.labelLoanCap}</div>
    </div>
  </div>
</div>
