<script lang="ts">
  import { rocket } from '../../stores/rocket.svelte.ts';
  import RocketCollapsibleSection from './RocketCollapsibleSection.svelte';

  let loan = $derived(rocket.snapshot.loan);
  let rt = $derived(rocket.realtime);
  let useRealtime = $derived(rt.loanActive ?? loan.active);
  let debtText = $derived(useRealtime ? rt.loanDebtText || loan.debtText : loan.debtText);
  let summaryText = $derived(rt.loanSummaryText || loan.summaryText);
  let debtBarPct = $derived(useRealtime ? rt.loanDebtBarPct : loan.debtBarPct);
  let debtStress = $derived(useRealtime ? rt.loanDebtStress : loan.debtStress);
  let statusText = $derived(useRealtime ? rt.loanStatusText || loan.statusText : loan.statusText);
  let active = $derived(useRealtime ? rt.loanActive ?? loan.active : loan.active);
  let borrowDisabled = $derived(useRealtime ? rt.loanBorrowDisabled ?? loan.borrowDisabled : loan.borrowDisabled);
  let cardAffordable = $derived(useRealtime ? rt.loanCardAffordable ?? loan.cardAffordable : loan.cardAffordable);
  let loanTooltip = $derived(`${loan.autoDeductionText}\n${loan.interestRateText}`);
</script>

<div class="tr-section">
  <RocketCollapsibleSection
    title={loan.loanTitle}
    tooltip={loanTooltip}
    {summaryText}
    statusPill={active ? 'Dette active' : 'Sans dette'}
    statusPillVariant={active ? 'warn' : 'ok'}
    id="rocketLoanCollapsible"
  >
    <div class="shop-item tr-loan-card" class:not-affordable={!cardAffordable} id="rocketLoanCard">
      <!-- Loan conditions summary strip -->
      <div class="tr-loan-conditions-strip">
        <span class="tr-loan-conditions-icon" aria-hidden="true">&#9432;</span>
        <span class="tr-loan-conditions-text">{loan.conditionsText}</span>
      </div>

      <!-- Single clean debt / borrowing line -->
      <div class="tr-loan-gauge-card">
        <div class="tr-loan-gauge-header">
          {#if active}
            <span class="tr-text-muted tr-text-muted--caps">Dette restante</span>
            <span class="tr-text-value tr-currency-gold" id="rocketLoanDebtText">{debtText}</span>
          {:else}
            <span class="tr-text-muted tr-text-muted--caps">Capacité d'emprunt</span>
            <span class="tr-text-value tr-currency-gold">{loan.loanCapValueFormatted}</span>
          {/if}
        </div>

        <!-- Fine repayment progress bar -->
        <div
          class="tr-loan-debt-track"
          class:tr-loan-debt-track--low={debtStress === 'low'}
          class:tr-loan-debt-track--mid={debtStress === 'mid'}
          class:tr-loan-debt-track--high={debtStress === 'high'}
        >
          <div
            id="rocketLoanDebtFill"
            class="tr-loan-debt-fill"
            class:has-progress={debtBarPct > 0}
            class:tr-loan-debt-fill--low={debtStress === 'low'}
            class:tr-loan-debt-fill--mid={debtStress === 'mid'}
            class:tr-loan-debt-fill--high={debtStress === 'high'}
            style:width="{debtBarPct}%"
          ></div>
        </div>

        <div
          class="tr-text-status"
          class:tr-text-status--warn={active}
          class:tr-text-status--ok={!active}
          id="rocketLoanStatusText"
        >
          {statusText}
        </div>
      </div>

      <!-- Action Row: Rembourser if active debt, Emprunter if no debt -->
      {#if active}
        <div class="tr-input-row tr-input-row--action" style="margin-top:10px;">
          <input
            id="rocketLoanRepayInput"
            class="tr-amount-input"
            type="text"
            inputmode="text"
            placeholder="Ex: 100M, Max..."
          />
          <div class="tr-preset-segmented" role="group" aria-label="Pourcentages de remboursement">
            <button type="button" class="tr-preset-segment" data-action="setRocketLoanRepayPreset" data-arg="0.25">25%</button>
            <button type="button" class="tr-preset-segment" data-action="setRocketLoanRepayPreset" data-arg="0.5">50%</button>
            <button type="button" class="tr-preset-segment" data-action="setRocketLoanRepayPreset" data-arg="0.75">75%</button>
            <button type="button" class="tr-preset-segment" data-action="setRocketLoanRepayPreset" data-arg="1">Max</button>
          </div>
          <button
            type="button"
            class="tr-preset-btn tr-action-btn tr-action-btn--primary tr-loan-repay-btn"
            id="rocketLoanRepayBtn"
            data-action="handleRocketRepayLoan"
            disabled={loan.repayDisabled}
          >
            {loan.repayButton}
          </button>
        </div>
      {:else}
        <div class="tr-input-row tr-input-row--action" style="margin-top:10px;">
          <input
            id="rocketLoanInput"
            class="tr-amount-input"
            type="text"
            inputmode="text"
            placeholder="Ex: 500M, Max..."
          />
          <div class="tr-preset-segmented" role="group" aria-label="Pourcentages d'emprunt">
            <button type="button" class="tr-preset-segment" data-action="setRocketLoanPreset" data-arg="0.25">25%</button>
            <button type="button" class="tr-preset-segment" data-action="setRocketLoanPreset" data-arg="0.5">50%</button>
            <button type="button" class="tr-preset-segment" data-action="setRocketLoanPreset" data-arg="0.75">75%</button>
            <button type="button" class="tr-preset-segment" data-action="setRocketLoanPreset" data-arg="1">Max</button>
          </div>
          <button
            type="button"
            class="tr-preset-btn tr-action-btn tr-action-btn--primary tr-loan-borrow-btn"
            id="rocketLoanBorrowBtn"
            data-action="handleRocketTakeLoan"
            disabled={borrowDisabled}
          >
            {loan.borrowButton}
          </button>
        </div>
      {/if}
    </div>
  </RocketCollapsibleSection>
</div>
